// === Tab: mySketch ===
// Disable the FES.
p5.disableFriendlyErrors = true;


let easycam;
let terrain = [];
let rows, cols;
let scl = 10;
let w = 500;
let h = 500;
let octaves = 4;
let persistence = 0.5;
let lacunarity = 2;
let currentRow = 0;
let currentParticle = 0;
let displaySpeed = 0.5;
let particles = [];
let partSize = 10;
let partSizeB = 5;
let partSizeC = 5;

let colorScale = chroma.scale(['#00429DF9', '#4771b2F9', '#73a2c6F9', 
															 '#A5D5D8E5', '#FFFFE0E8', '#ffbcafF9', 
															 '#F4777FEF', '#CF3759ED', '#93003AEA']).domain([-100, 100]);
let colorScale1 = chroma.scale(['#A6DA87ED', '#72DC61EA', '#35C059ED', 
															 '#34DF69B7', '#FFFFE0BA', '#955F544C', 
															 '#985D60A5', '#966671AA', '#93003A99']).domain([-100, 100]);
let colorScale2 = chroma.scale(['#4F7098', '#74C3D8', '#7C99CB', '#76A3E7', '#FFFFFF']).domain([-50, 50]);
let colorScale3 = chroma.scale(['#FFCA41', '#F4FD74', '#F7FDC8']).domain([-50, 50]);
let colorScale4 = chroma.scale(['#E288ECD1', '#74F0FDED', '#5B6BB16D']).domain([-50, 50]);

function setup() {
  createCanvas(windowHeight*4/3, windowHeight, WEBGL);
	//setAttributes('antialias', true);
	//console.log(Dw.EasyCam.INFO);
//  easycam = createEasyCam({distance: 1000, center: [0,-300,0],rotation: [QUARTER_PI*0.8,-QUARTER_PI,PI/12,PI/12]});
  easycam = createEasyCam({distance: 900, center: [0,0,0],rotation: [0.4,-0.75,0,0]});
  rows = h / scl;
  cols = w / scl;
	//randomSeed(56789);
  for (let x = 0; x < cols; x++) {
    terrain[x] = [];
  }

  centerX = cols / 2;
  centerY = rows / 2;
  radius = Math.min(rows, cols) / 2;

  generateTerrain();
  createParticles();

	ambientLight(60);
	pointLight(255,255,255,100,100,100);
}

function draw() {
	//perspective(60 * PI/180, width/height, 1, 5000);
	if (frameCount==20) save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
	translate(0,-150,-50); 
  background(20);
  translate(-w / 2, -h / 2);
  stroke(0);

  updateParticles();
  drawParticles();
	drawParticlesB();
  drawParticlesC();

}

function createHatchPatternA(color) {
  let pattern = createGraphics(20, 20);
  pattern.stroke(color);
  pattern.strokeWeight(1);
  pattern.line(0, 0, 20, 20);
  pattern.line(20, 0, 0, 20);
	pattern.circle(10,10,10);
	pattern.line(10,10,20,20);
	pattern.line(20,10,20,20);
  return pattern;
}

function generateTerrain() {
  let yoff = 0;
  for (let y = 0; y < rows; y++) {
    let xoff = 0;
    for (let x = 0; x < cols; x++) {
      terrain[x][y] = map(fBm(xoff, yoff), 0, 1, -100, 100);
      xoff += 0.1;
    }
    yoff += 0.1;
  }
}

function fBm(x, y) {
  let sum = 0;
  let amplitude = 1;
  let frequency = 1;
  let maxValue = 0;

  for (let i = 0; i < octaves; i++) {
    sum += amplitude * noise(x * frequency, y * frequency);
    maxValue += amplitude;
    amplitude *= persistence;
    frequency *= lacunarity;
  }

  return sum / maxValue;
}

function createParticles() {
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      let particle = {
        x: x * scl * random(0.97, 1.03),
        y: y * scl,
        z: -300,
        targetZ: terrain[x][y],
        hatchPattern: createHatchPatternA(colorScale1(terrain[x][y]).hex())
      };
      particles.push(particle);
    }
  }
}


function updateParticles() {
  for (let i = 0; i < particles.length; i++) {
    let x = particles[i].x / scl;
    let y = particles[i].y / scl;

    let updateRange = 5; 
    let lowerBound = (currentRow - updateRange + rows) % rows;
    let upperBound = (currentRow + updateRange) % rows;

    if (lowerBound <= upperBound) {
      if (y >= lowerBound && y <= upperBound) {
        particles[i].z = lerp(particles[i].z, particles[i].targetZ, 0.1);
      }
    } else {
      if (y >= lowerBound || y <= upperBound) {
        particles[i].z = lerp(particles[i].z, particles[i].targetZ, 0.1);
      }
    }
  }

  currentRow = (currentRow + displaySpeed) % rows;
}


function drawParticles() {
  for (let i = 0; i < particles.length; i++) {
    push();
    //texture(particles[i].hatchPattern);
		fill(colorScale(particles[i].targetZ).hex());
    translate(particles[i].x, particles[i].y, particles[i].z);
    //box(partSize);
		rotateX(HALF_PI);
		randomSeed(HALF_PI*i*10);
		//noStroke();
		box(partSize,partSize*random(5), Math.floor(randomGaussian(8,12)),  Math.floor(randomGaussian(2,4)),  2);
    pop();
  }
}


function drawParticlesB() {
  for (let i = 0; i < particles.length; i++) {
    push();
		texture(particles[i].hatchPattern);
    //fill(colorScale3(particles[i].targetZ).hex());
		stroke(colorScale3(particles[i].targetZ).lab());
    translate(particles[i].x * 0.3, particles[i].y * 0.3, particles[i].z * 3);
		translate(350,300,-100);
		noStroke();
    //strokeWeight(0.5);
    sphere(partSizeB);
    pop();
  }
}

function drawParticlesC() {
  let particleIndex = 0;
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      let dx = x - centerX;
      let dy = y - centerY;
      //let distance = Math.sqrt(dx * dx + dy * dy);
      //let distance = Math.sqrt((dx * dx) * (dy * dy));
      let distance = Math.sqrt((dx * cos(PI / 7 * x * y)) + (dy * sin(TWO_PI * y + x)));

      if (distance < radius) {
        push();
					//texture(particles[particleIndex].hatchPattern);
          fill(colorScale4(particles[particleIndex].targetZ).hex());
          translate(particles[particleIndex].x, particles[particleIndex].y, particles[particleIndex].z * 1.2);
          //noStroke();
					stroke(colorScale3(particles[particleIndex].targetZ).lab());
					strokeWeight(0.3);
					translate(-50,-50,-20);
					rotateX(HALF_PI);
					randomSeed(PI*x*y);
          cylinder(partSizeC,partSizeC*random(2,25), Math.floor(randomGaussian(6,10)), 4);
					//x1, y1, z1, x2, y2, z2, x3, y3, z3, x4, y4, z4
					//bezier(partSizeC/2,partSizeC/2, partSizeC/4,partSizeC/4, partSizeC*1.5,partSizeC*1.5, partSizeC*2,partSizeC*2);
        pop();
      }
      particleIndex++;
    }
  }
}



// === Tab: utils ===

function clamp(min, max, val) {
    return Math.min(Math.max(min, +val), max);
}

function mousePressed() {
	redraw();
}

function keyTyped() {
	if (key === "s" || key === "S") {
		saveCanvas("foret_de_mots", "png");
	}
}

